def fibonacci(n):
    if n == 0:
        return [0]
    elif n == 1:
        return [0, 1]
    fib = [0, 1]
    for i in range(2, n + 1):
        fib.append(fib[i-2] + fib[i-1])
    return fib

def max_subarray_sum(numbers, k):
    if not numbers or k <= 0:
        return 0
    current_sum = sum(numbers[:k])
    max_sum = current_sum
    for i in range(1, len(numbers) - k + 1):
        current_sum += numbers[i + k - 1] - numbers[i - 1]
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True
